SET
  @ID_35d7370b = '0A9F0FDD-CD4D-4892-BA45-85722B982032' EXEC [${mjSchema}].spUpdateSchemaInfo @SchemaName = @SchemaName_35d7370b,
  @EntityIDMin = @EntityIDMin_35d7370b,
  @EntityIDMax = @EntityIDMax_35d7370b,
